    public String csv(String name, String rawPeriod) {
        ReportType type = types.stream().filter(t -> t.name().equals(name)).findFirst()
                .orElseThrow(() -> ApiException.invalid("Relatório desconhecido: " + name));
        return csv(type, rawPeriod);
    }
}
