            }
            json(ctx, 200, arr);
        });

        for (ReportType type : reports.types()) {
            app.get("/reports/" + type.name(), ctx -> {
                String csv = reports.csv(type, ctx.queryParam(type.periodParam()));
                ctx.contentType("text/csv; charset=utf-8").result(csv);
            });
        }
        return app;
